exec(open('bp.py').read().split('# ---------- shared components')[0])
def head_imports(k,reverse=False,pk=True,pkg=True):
    r=' reverse="{{ true }}"' if reverse else ''
    s=f'<dc-import name="SiteHeader" hint-size="100%,88px"></dc-import>\n<dc-import name="PageHero" page="{k}" heading="{NAMES[k]}" hint-size="100%,720px"></dc-import>\n<dc-import name="IntroSplit" page="{k}"{r} hint-size="100%,1500px"></dc-import>\n'
    return s
def tail_imports(k,pkg=True):
    s=''
    if pkg: s+=f'<dc-import name="Packages" page="{k}" hint-size="100%,960px"></dc-import>\n'
    s+=f'<dc-import name="Folyamat" page="{k}" hint-size="100%,1900px"></dc-import>\n<dc-import name="ProcessFaq" page="{k}" hint-size="100%,1100px"></dc-import>\n<dc-import name="SiteFooter" current="{NAMES[k]}" hint-size="100%,1780px"></dc-import>\n'
    return s
def page(k,reverse,mid,script,h,pkg=True):
    body=f'<div style="width:100%;background:#1a1a1a;color:#1a1a1a;font-family:Inter,system-ui,sans-serif">\n'+head_imports(k,reverse)+mid+tail_imports(k,pkg)+'</div>'
    return doc(NAMES[k],body,script,h)
def hdr(e,t,c1='#006633',c2='#1a1a1a',extra=''):
    return f'<div style="display:flex;flex-direction:column;gap:16px;max-width:760px">{eyebrow(e,c1)}{h2(t,c2)}{extra}</div>'
def sec(bg,inner,gap=48): return f'<section style="background:{bg}"><div style="max-width:1440px;margin:0 auto;padding:clamp(48px,8vw,96px) clamp(20px,5.5vw,80px);display:flex;flex-direction:column;gap:{gap}px">{inner}</div></section>\n'
def lead(t,c='rgba(26,26,26,.78)'): return f'<p style="font-size:18px;line-height:1.65;color:{c}">{t}</p>'
def S(js): return 'class Component extends DCLogic {\nrenderVals() {\nreturn '+js+';\n}\n}'
